<template><AppShell><header class="page-head"><span class="eyebrow"><Library :size="15" />PERSONALIZED RESOURCES</span><h1>资源中心</h1><p>查看题库、文档、课件、导图、视频和动画的服务端历史。</p></header>
  <RouterLink class="create-resource-band" to="/resources/new"><span><WandSparkles :size="23" /></span><div><strong>生成新资源</strong><small>统一轻量表单 · 后台持续处理</small></div><ArrowRight :size="19" /></RouterLink>
  <div class="chip-row"><button v-for="item in filters" :key="item.value" :class="{active:filter===item.value}" @click="filter=item.value">{{ item.label }}</button></div>
  <AsyncState :loading="loading" :error="error" :empty="!filtered.length" empty-text="该分类暂无服务端任务" @retry="load"><div class="resource-list"><RouterLink v-for="task in filtered" :key="task.taskId" class="resource-row" :to="`/resources/task/${task.taskId}`"><span class="resource-kind" :class="task.taskType"><component :is="iconFor(task.taskType)" :size="22" /></span><div><span class="status-pill" :class="task.status">{{ statusText(task.status) }}</span><h2>{{ task.title||typeName(task.taskType) }}</h2><p>{{ typeName(task.taskType) }} · {{ formatDate(task.updatedAt||task.createdAt) }}</p></div><ChevronRight :size="18" /></RouterLink></div></AsyncState>
  </AppShell></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { ArrowRight,BookOpenCheck,ChevronRight,Clapperboard,FileText,Library,Network,Presentation,WandSparkles } from 'lucide-vue-next';import { RouterLink } from 'vue-router';import AppShell from '../components/AppShell.vue';import AsyncState from '../components/AsyncState.vue';import { getTaskHistory } from '../services/api.js';import { trackTask } from '../stores/tasks.js';import { formatDate,resourceTypeName,taskList } from '../utils/data.js'
const tasks=ref([]),loading=ref(true),error=ref(''),filter=ref('all');const filters=[{value:'all',label:'全部'},{value:'running',label:'生成中'},{value:'question_bank',label:'题库'},{value:'document',label:'文档'},{value:'ppt',label:'PPT'},{value:'mindmap',label:'导图'},{value:'video',label:'视频'}]
const filtered=computed(()=>filter.value==='all'?tasks.value:filter.value==='running'?tasks.value.filter(x=>['queued','running','waiting'].includes(x.status)):tasks.value.filter(x=>x.taskType===filter.value||(filter.value==='video'&&x.taskType.includes('video'))))
async function load(){loading.value=true;error.value='';try{tasks.value=taskList(await getTaskHistory(100));tasks.value.filter(t=>['queued','running'].includes(t.status)).forEach(trackTask)}catch(e){error.value=e.message}finally{loading.value=false}}
function statusText(s){return {queued:'排队中',running:'生成中',complete:'已完成',failed:'生成失败',waiting:'待确认',cancelled:'已取消'}[s]||s}function typeName(t){return resourceTypeName(t)}function iconFor(t){return t==='question_bank'?BookOpenCheck:t==='ppt'?Presentation:t==='mindmap'?Network:/video|animation/.test(t)?Clapperboard:FileText}onMounted(load)
</script>
<style scoped>.create-resource-band{min-height:76px;display:grid;grid-template-columns:44px minmax(0,1fr) 20px;align-items:center;gap:12px;margin-bottom:14px;padding:14px;border:1px solid #cfe0d7;border-radius:7px;background:#eef7f2;color:#176f4b}.create-resource-band>span{width:44px;height:44px;display:grid;place-items:center;border-radius:6px;background:#176f4b;color:white}.create-resource-band strong,.create-resource-band small{display:block}.create-resource-band strong{color:#20342b;font-size:14px}.create-resource-band small{margin-top:4px;color:#64766d;font-size:10px}.resource-list{display:grid;gap:8px;margin-top:16px}.resource-row{min-height:88px;display:grid;grid-template-columns:46px minmax(0,1fr) 20px;align-items:center;gap:12px;padding:12px 13px;border:1px solid #dce5e0;border-radius:7px;background:white}.resource-kind{width:46px;height:46px;display:grid;place-items:center;border-radius:6px;background:#edf5f1;color:#176f4b}.resource-kind.ppt{background:#edf4fb;color:#2f68b2}.resource-kind.mindmap{background:#f2eef8;color:#7054a0}.resource-kind.video,.resource-kind.generated_video{background:#e9f5f4;color:#137f7b}.resource-row h2{margin:6px 0 0;font-size:13px;line-height:1.4}.resource-row p{margin:4px 0 0;color:#78857e;font-size:9px}</style>
